import { sql } from 'drizzle-orm'
import { drizzle } from 'drizzle-orm/node-postgres'
import { migrate } from 'drizzle-orm/node-postgres/migrator'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { createDatabase, type Database } from './index'
import * as schema from './schema'

/**
 * Migration runner.
 *
 * Used by `pnpm db:migrate` and by the container entrypoint, so a fresh
 * deployment comes up with a schema without a manual step.
 *
 * Migrations are plain SQL files generated by drizzle-kit and tracked in a
 * journal table, so re-running is a no-op.
 */

const HERE = path.dirname(fileURLToPath(import.meta.url))

/** Where drizzle-kit's generated SQL lives, relative to this file. */
function migrationsFolder(): string {
  return path.join(HERE, 'migrations')
}

/** Drizzle's journal table. Named here once so the count and the migrator agree. */
const MIGRATIONS_TABLE = '__drizzle_migrations'

export interface MigrateResult {
  applied: number
  durationMs: number
}

export async function runMigrations(
  connectionString: string,
): Promise<MigrateResult> {
  const started = Date.now()
  const { pool, close } = createDatabase(connectionString)

  try {
    // Advisory locks belong to a PostgreSQL session. Keep the lock, migration
    // transaction and unlock on one checked-out connection; Pool.query() can
    // otherwise release a different connection's lock after the transaction.
    const client = await pool.connect()
    try {
      const db = drizzle(client, { schema, casing: 'snake_case' })
      await db.execute(sql`select pg_advisory_lock(${727_101_501})`)
      try {
        // `migrate()` reports nothing, so the count is taken around it. The table
        // may not exist yet on a virgin database, and a missing table is not an
        // error here — it means zero migrations have ever run, which is what the
        // count should say.
        const before = await countApplied(db)

        await migrate(db, {
          migrationsFolder: migrationsFolder(),
          migrationsTable: MIGRATIONS_TABLE,
          migrationsSchema: 'public',
        })

        const after = await countApplied(db)

        return { applied: Math.max(0, after - before), durationMs: Date.now() - started }
      } finally {
        await db.execute(sql`select pg_advisory_unlock(${727_101_501})`)
      }
    } finally {
      client.release()
    }
  } finally {
    await close()
  }
}

/**
 * How many migrations the journal holds.
 *
 * Existence is asked as a question (`to_regclass`) rather than discovered by
 * catching a failure. A select against a missing table raises, and the raise
 * aborts the enclosing transaction — recovering from that needs a savepoint and
 * a borrowed `catch`, both of which are more machinery than the answer is
 * worth. `to_regclass` returns null instead of raising.
 *
 * `count(*)` comes back as `bigint`, which node-postgres hands over as a string
 * because it cannot be represented exactly in a JS number. Parsing it is the
 * correct handling, not a shortcut.
 */
async function countApplied(db: Database): Promise<number> {
  const exists = await db.execute<{ present: boolean }>(
    sql`select to_regclass(${MIGRATIONS_TABLE}) is not null as present`,
  )
  if (!exists.rows[0]?.present) return 0

  const counted = await db.execute<{ count: string }>(
    sql`select count(*)::text as count from ${sql.identifier(MIGRATIONS_TABLE)}`,
  )

  return Number.parseInt(counted.rows[0]?.count ?? '0', 10)
}
